package com.example.gameworkbench.service;
import static org.assertj.core.api.Assertions.assertThat; import java.util.List; import java.util.Map; import org.junit.jupiter.api.Test;
class RetrievalServiceTest { @Test void enforcesProjectAndStatus(){ var store=new InMemoryVectorStore(); var provider=new FakeEmbeddingProvider(); store.upsert("a",provider.embed(List.of("q")).getFirst(),Map.of("projectId","1","status","ACTIVE","chunkUuid","c","documentUuid","d","documentVersion","1","embeddingModel",provider.model(),"textRef","text-a")); store.upsert("b",provider.embed(List.of("q")).getFirst(),Map.of("projectId","2","status","ACTIVE","chunkUuid","x","documentUuid","z","documentVersion","1","embeddingModel",provider.model(),"textRef","text-b")); var out=new ProjectRetrievalService(provider,store).retrieve(new RetrievalRequest(1L,"q",5,0,100)); assertThat(out).hasSize(1); assertThat(out.getFirst().chunkUuid()).isEqualTo("c"); } }
